using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

namespace BeatFactory
{
    /// <summary>
    /// All layered sprites of the customizable player (generated by the editor art tool; replace PNGs with final art).
    /// Every layer of a body part has the same canvas size and pivot, so layers stack perfectly.
    /// </summary>
    [CreateAssetMenu(fileName = "AvatarLibrary", menuName = "Beat Factory/Avatar Library")]
    public class AvatarLibrary : ScriptableObject
    {
        [Header("Head (160×160)")]
        public Sprite[] faces = new Sprite[6];
        public Sprite[] hairBack;
        public Sprite[] hairFront;
        public Sprite cap, beanie, headphones, glassesRound, sunglasses, earrings, tattooFace;

        [Header("Body (200×190)")]
        public Sprite bodyBase;
        public Sprite[] tops;
        public Sprite[] pantsFar, pantsNear, pantsHem;
        public Sprite[] shoesFar, shoesNear;
        public Sprite chainThin, chainCuban, tattooNeck;

        [Header("Arm (56×140)")]
        public Sprite[] sleeves;
        public Sprite hand, tattooArm, tattooHand, watchSmart, watchGold, rings;

        [Header("Menu thumbnails")]
        public List<string> thumbKeys = new List<string>();
        public List<Sprite> thumbSprites = new List<Sprite>();

        public Sprite Thumb(AvatarSlot slot, int value)
        {
            int i = thumbKeys.IndexOf(AvatarCatalog.Key(slot, value));
            return i >= 0 ? thumbSprites[i] : null;
        }

        public static Sprite At(Sprite[] array, int index) =>
            array != null && index >= 0 && index < array.Length ? array[index] : null;
    }
}

